import numpy as np
A={L:np.asarray(r3[f"attention.{L}"]) for L in range(18)}
# recompute regions from texts2/meta2
qregs=[]; gregs=[]
for j,(s,(i,cond)) in enumerate(zip(texts2,meta2)):
    enc=tokenizer.encode(s); shift=len(enc.ids)-len(r3["tokens"][j])
    us=s.index("user\n")+5
    qend=s.index(" I think") if cond!="none" else s.index("<end_of_turn>")
    def idxs(a,b):
        return [k-shift for k,(st,en) in enumerate(enc.offsets) if not (en<=a or st>=b) and k-shift>=0]
    qregs.append(idxs(us,qend))
    if cond=="none": gregs.append([])
    else:
        word=facts[i]["correct"] if cond=="correct" else facts[i]["guess"]
        a=s.index("I think the answer is ")+len("I think the answer is "); b=a+len(word)
        gregs.append(idxs(a,b))
for L in range(18):
    rows=[]
    for h in range(4):
        vals={}
        for cond in ["none","correct","wrong"]:
            js=[j for j,(i,c) in enumerate(meta2) if c==cond]
            qm=np.mean([A[L][j][h][qregs[j]].sum() for j in js])
            gm=np.mean([A[L][j][h][gregs[j]].sum() if gregs[j] else 0 for j in js])
            vals[cond]=(qm,gm)
        rows.append((h,vals))
    print("LAYER",L)
    for h,vals in rows:
        print(" h",h," ".join(f"{c}:q{vals[c][0]:.2f}/g{vals[c][1]:.2f}" for c in ["none","wrong"]))
